repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 50), ('plaza', 56), ('lodge', 34), ('grand', 44), ('plaza', 54)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.summary.py:
"""Summary of bookings."""


class BookingSummary:
    def __init__(self, bookings):
        self._bookings = bookings

    def count(self):
        """Return how many bookings there are."""
        return sum(1 for _ in self._bookings)

    def mean_nights(self):
        """Return the mean nights, or 0.0 when there are no bookings."""
        total = sum(x.nights for x in self._bookings)
        n = self.count()
        return total / n if n else 0.0


def hotel_names(bookings):
    """Return the distinct hotel values, in first-seen order."""
    names = []
    for x in bookings:
        if x.hotel not in names:
            names.append(x.hotel)
    return names


def largest_nights(bookings):
    """Return the largest nights, or None when there are no bookings."""
    values = [x.nights for x in bookings]
    return max(values) if values else None
